177	// Temp arrays (static to stay off the task stack)
178	static float s_ord[5][WIN_SIZE];       // ring buffer in temporal order
179	static float s_srt[5][WIN_SIZE];       // sorted versions
180	static float s_diff[3][DIFF_SIZE];     // [0]=|thr_diff| [1]=|brk_diff| [2]=|jerk|
