183	static int float_cmp(const void *a, const void *b)
184	{
185	    float fa = *(const float *)a;
186	    float fb = *(const float *)b;
187	    return (fa > fb) - (fa < fb);
188	}
189	
190	// Linear interpolation percentile matching numpy default (method='linear')
191	static float percentile_sorted(const float *sorted, int n, float p)
192	{
193	    float idx = p * (float)(n - 1);
194	    int lo = (int)idx;
195	    int hi = lo + 1;
196	    if (hi >= n) return sorted[n - 1];
197	    return sorted[lo] + (idx - (float)lo) * (sorted[hi] - sorted[lo]);
198	}
199	
200	static float arr_mean(const float *arr, int n)
201	{
202	    float s = 0.0f;
203	    for (int i = 0; i < n; i++) s += arr[i];
204	    return s / (float)n;
205	}
206	
207	// Population std (ddof=0), matching numpy default
208	static float arr_std(const float *arr, int n, float m)
209	{
210	    float v = 0.0f;
211	    for (int i = 0; i < n; i++) {
212	        float d = arr[i] - m;
213	        v += d * d;
214	    }
215	    return sqrtf(v / (float)n);
216	}
217	
218	static int16_t clamp_i16(float v)
219	{
220	    if (v > (float)INT16_MAX) return INT16_MAX;
221	    if (v < (float)INT16_MIN) return INT16_MIN;
222	    return (int16_t)lrintf(v);
223	}
