263	static void reset_window(void)
264	{
265	    memset(s_buf,   0, sizeof(s_buf));
266	    s_buf_head   = 0;
267	    s_buf_count  = 0;
268	    s_last_ts    = 0;
269	    s_last_spd_ms = 0.0f;
270	}
271	
272	void ai_model_init(void)
273	{
274	    reset_window();
275	    s_score = AI_SCORE_START;
276	    s_style = AI_DRIVING_STYLE_NORMAL;
277	    s_ready = false;
278	    s_aggr_streak = 0;
279	    s_withered = false;
280	    ai_orchard_nvs_load();
281	}
282	
283	void ai_model_process_sample(const can_data_t *data)
284	{
285	    if (data == NULL) return;
286	
287	    // Mirror training-data filters: ignition on, not in reverse, not stopped (speed_mean >= 2 km/h)
288	    if (!data->ignition || data->rear_gear || data->speed < 2) {
289	        reset_window();
290	        s_style = AI_DRIVING_STYLE_NORMAL;
291	        s_ready = false;
292	        s_aggr_streak = 0;  // standing still is not aggression; s_withered stays latched
293	        return;
294	    }
295	
296	    float dt_s = 0.1f;
297	    if (s_last_ts > 0 && data->timestamp > s_last_ts) {
298	        dt_s = (float)(data->timestamp - s_last_ts) / 1000.0f;
299	        if (dt_s < 0.01f) dt_s = 0.01f;
300	    }
301	    s_last_ts = data->timestamp;
302	
303	    float spd_ms = (float)data->speed / 3.6f;
304	    float accel  = (spd_ms - s_last_spd_ms) / dt_s;
305	    s_last_spd_ms = spd_ms;
306	
307	    s_buf[0][s_buf_head] = (float)data->speed;
308	    s_buf[1][s_buf_head] = (float)data->rpm;
309	    s_buf[2][s_buf_head] = (float)data->throttle_pedal;
310	    s_buf[3][s_buf_head] = (float)data->brake_pedal;
311	    s_buf[4][s_buf_head] = accel;
312	    s_buf_head = (s_buf_head + 1) % WIN_SIZE;
313	    if (s_buf_count < WIN_SIZE) s_buf_count++;
314	
315	    if (s_buf_count < WIN_SIZE) {
316	        s_ready = false;
317	        return;
318	    }
319	
320	    // Unroll ring buffer into temporal order (oldest → newest)
321	    for (int b = 0; b < 5; b++) {
322	        for (int i = 0; i < WIN_SIZE; i++) {
323	            s_ord[b][i] = s_buf[b][(s_buf_head + i) % WIN_SIZE];
324	        }
325	        memcpy(s_srt[b], s_ord[b], WIN_SIZE * sizeof(float));
326	        qsort(s_srt[b], WIN_SIZE, sizeof(float), float_cmp);
327	    }
328	
329	    // Per-second derivatives (divide by DT, matching notebook d_*_s = diff / DT):
330	    //  [0] d_throttle_s (signed), [1] d_brake_s (signed), [2] |jerk_ms3| (abs)
331	    // throttle/brake keep their sign — *_dp95 takes the upper tail (sharp presses),
332	    // so signed vs abs matters when releases are sharper than presses.
333	    const float inv_dt = 1.0f / DT_S;
334	    for (int i = 0; i < DIFF_SIZE; i++) {
335	        s_diff[0][i] = (s_ord[2][i + 1] - s_ord[2][i]) * inv_dt;
336	        s_diff[1][i] = (s_ord[3][i + 1] - s_ord[3][i]) * inv_dt;
337	        s_diff[2][i] = fabsf(s_ord[4][i + 1] - s_ord[4][i]) * inv_dt;
338	    }
339	    for (int d = 0; d < 3; d++) {
340	        memcpy(s_srt_diff[d], s_diff[d], DIFF_SIZE * sizeof(float));
341	        qsort(s_srt_diff[d], DIFF_SIZE, sizeof(float), float_cmp);
342	    }
343	
344	    float spd_mean = arr_mean(s_ord[0], WIN_SIZE);
345	    float rpm_mean = arr_mean(s_ord[1], WIN_SIZE);
346	    float thr_mean = arr_mean(s_ord[2], WIN_SIZE);
347	    float brk_mean = arr_mean(s_ord[3], WIN_SIZE);
348	    float a_mean   = arr_mean(s_ord[4], WIN_SIZE);
349	
350	    float abs_a_mean = 0.0f;
351	    for (int i = 0; i < WIN_SIZE; i++) abs_a_mean += fabsf(s_ord[4][i]);
352	    abs_a_mean /= (float)WIN_SIZE;
353	
354	    float raw[FEAT_COUNT];
355	    raw[0]  = spd_mean;
356	    raw[1]  = arr_std(s_ord[0], WIN_SIZE, spd_mean);
357	    raw[2]  = percentile_sorted(s_srt[0], WIN_SIZE, 0.95f);
358	    raw[3]  = rpm_mean;
359	    raw[4]  = arr_std(s_ord[1], WIN_SIZE, rpm_mean);
360	    raw[5]  = percentile_sorted(s_srt[1], WIN_SIZE, 0.95f);
361	    raw[6]  = thr_mean;
362	    raw[7]  = arr_std(s_ord[2], WIN_SIZE, thr_mean);
363	    raw[8]  = percentile_sorted(s_srt[2], WIN_SIZE, 0.95f);
364	    raw[9]  = percentile_sorted(s_srt_diff[0], DIFF_SIZE, 0.95f);
365	    raw[10] = brk_mean;
366	    raw[11] = percentile_sorted(s_srt[3], WIN_SIZE, 0.95f);
367	    raw[12] = percentile_sorted(s_srt_diff[1], DIFF_SIZE, 0.95f);
368	    raw[13] = a_mean;
369	    raw[14] = arr_std(s_ord[4], WIN_SIZE, a_mean);
370	    raw[15] = percentile_sorted(s_srt[4], WIN_SIZE, 0.95f);
371	    raw[16] = percentile_sorted(s_srt[4], WIN_SIZE, 0.05f);
372	    raw[17] = abs_a_mean;
373	    raw[18] = arr_mean(s_diff[2], DIFF_SIZE);
374	    raw[19] = percentile_sorted(s_srt_diff[2], DIFF_SIZE, 0.95f);
375	
376	    int16_t features[FEAT_COUNT];
377	    for (int i = 0; i < FEAT_COUNT; i++) {
378	        features[i] = clamp_i16(raw[i] * AI_FEAT_SCALE[i] + AI_FEAT_MIN[i]);
379	    }
380	
381	    int pred = (int)AI_MODEL_PREDICT(features, FEAT_COUNT);
382	    if (pred < 0 || pred > 2) return;
383	
384	    s_style = (ai_driving_style_t)pred;
385	    s_ready = true;
386	
387	    if (s_style == AI_DRIVING_STYLE_ECO && s_score < AI_SCORE_MAX) {
388	        s_score += AI_SCORE_ECO_STEP;
389	    } else if (s_style == AI_DRIVING_STYLE_AGGRESSIVE && s_score > AI_SCORE_MIN) {
390	        s_score -= AI_SCORE_AGGRESSIVE_STEP;
391	    }
392	    if (s_score < AI_SCORE_MIN) s_score = AI_SCORE_MIN;
393	    if (s_score > AI_SCORE_MAX) s_score = AI_SCORE_MAX;
394	
395	    // Harvest: a fully fruiting tree (score at MAX) moves to the orchard and a
396	    // new tree starts from the neutral score.
397	    if (s_score >= AI_SCORE_MAX) {
398	        s_orchard_count++;
399	        ai_orchard_nvs_save();
400	        eco_stats_on_tree_harvested();
401	        s_score = AI_SCORE_START;
402	        ESP_LOGI(TAG, "Tree harvested, orchard count: %lu", (unsigned long)s_orchard_count);
403	    }
404	
405	    // Track sustained aggression for the eco-tree wither state (with hysteresis):
406	    // wither after a run of aggressive windows; revive only once eco driving
407	    // pulls the score back up.
408	    if (s_style == AI_DRIVING_STYLE_AGGRESSIVE) {
409	        if (s_aggr_streak < UINT32_MAX) s_aggr_streak++;
410	    } else {
411	        s_aggr_streak = 0;
412	    }
413	    if (s_aggr_streak >= AI_TREE_WITHER_WINDOWS) {
414	        // Wither transition costs one orchard tree (once per wither event —
415	        // s_withered stays latched until the score recovers).
416	        if (!s_withered) {
417	            s_withered = true;
418	            eco_stats_on_tree_withered();
419	            if (s_orchard_count > 0) {
420	                s_orchard_count--;
421	                ai_orchard_nvs_save();
422	                ESP_LOGI(TAG, "Tree withered, orchard count: %lu", (unsigned long)s_orchard_count);
423	            }
424	        }
425	    } else if (s_withered && s_score >= AI_TREE_REVIVE_SCORE) {
426	        s_withered = false;
427	    }
428	}
