430	void ai_model_get_snapshot(ai_model_snapshot_t *out_snapshot)
431	{
432	    if (out_snapshot == NULL) return;
433	    out_snapshot->score = s_score;
434	    out_snapshot->style = s_style;
435	    out_snapshot->ready = s_ready;
436	}
