438	// Map driver state to an eco-tree stage: 0 = withered, 1..6 = growth bands of score.
439	static int ai_tree_stage_from_state(int32_t score, bool withered)
440	{
441	    if (withered) return 0;
442	    int band = (int)((score - AI_SCORE_MIN) * AI_TREE_GROWTH_STAGES
443	                     / (AI_SCORE_MAX - AI_SCORE_MIN + 1));  // 0..5
444	    if (band < 0) band = 0;
445	    if (band > AI_TREE_GROWTH_STAGES - 1) band = AI_TREE_GROWTH_STAGES - 1;
446	    return band + 1;  // 1..6
447	}
