449	// Create the split AI view once:
450	// left half = currently growing tree, right half = orchard of harvested trees.
451	static void ai_tree_ensure_created(void)
452	{
453	    if (s_tree_img != NULL || objects.container_can_1 == NULL) return;
454	
455	    lv_obj_t *parent = objects.container_can_1;
456	
457	    // Drop the generated pad_top so children span the full screen height.
458	    lv_obj_set_style_pad_top(parent, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
459	
460	    // Full-screen meadow background: pale grass with a halo behind the growing
461	    // tree on the left, blending into a denser meadow under the orchard.
462	    lv_obj_set_style_bg_img_src(parent, &eco_meadow_bg, LV_PART_MAIN | LV_STATE_DEFAULT);
463	
464	    // Left half: the currently growing tree (live driving status).
465	    lv_obj_t *left = lv_obj_create(parent);
466	    lv_obj_remove_style_all(left);
467	    lv_obj_add_flag(left, LV_OBJ_FLAG_IGNORE_LAYOUT);
468	    lv_obj_clear_flag(left, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
469	    lv_obj_set_size(left, LV_PCT(50), LV_PCT(100));
470	    lv_obj_align(left, LV_ALIGN_LEFT_MID, 0, 0);
471	
472	    s_tree_img = lv_img_create(left);
473	    lv_obj_clear_flag(s_tree_img, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
474	    lv_obj_align(s_tree_img, LV_ALIGN_CENTER, 0, AI_TREE_Y_OFFSET);
475	
476	    // Trip-savings pill, sitting in the space freed up above the tree.
477	    s_money_pill = lv_obj_create(left);
478	    lv_obj_remove_style_all(s_money_pill);
479	    lv_obj_add_flag(s_money_pill, LV_OBJ_FLAG_IGNORE_LAYOUT);
480	    lv_obj_clear_flag(s_money_pill, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
481	    lv_obj_set_size(s_money_pill, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
482	    lv_obj_set_style_bg_color(s_money_pill, lv_color_hex(0xffffffff), LV_PART_MAIN | LV_STATE_DEFAULT);
483	    lv_obj_set_style_bg_opa(s_money_pill, 95, LV_PART_MAIN | LV_STATE_DEFAULT);
484	    lv_obj_set_style_radius(s_money_pill, LV_RADIUS_CIRCLE, LV_PART_MAIN | LV_STATE_DEFAULT);
485	    lv_obj_set_style_border_color(s_money_pill, lv_color_hex(0xff2E7D32), LV_PART_MAIN | LV_STATE_DEFAULT);
486	    lv_obj_set_style_border_opa(s_money_pill, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
487	    lv_obj_set_style_border_width(s_money_pill, 3, LV_PART_MAIN | LV_STATE_DEFAULT);
488	    lv_obj_set_style_shadow_color(s_money_pill, lv_color_hex(0xff2E7D32), LV_PART_MAIN | LV_STATE_DEFAULT);
489	    lv_obj_set_style_shadow_opa(s_money_pill, 120, LV_PART_MAIN | LV_STATE_DEFAULT);
490	    lv_obj_set_style_shadow_width(s_money_pill, 14, LV_PART_MAIN | LV_STATE_DEFAULT);
491	    lv_obj_set_style_shadow_spread(s_money_pill, 1, LV_PART_MAIN | LV_STATE_DEFAULT);
492	    lv_obj_set_style_pad_hor(s_money_pill, 28, LV_PART_MAIN | LV_STATE_DEFAULT);
493	    lv_obj_set_style_pad_ver(s_money_pill, 14, LV_PART_MAIN | LV_STATE_DEFAULT);
494	    lv_obj_set_flex_flow(s_money_pill, LV_FLEX_FLOW_COLUMN);
495	    lv_obj_set_flex_align(s_money_pill, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
496	    lv_obj_set_style_pad_row(s_money_pill, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
497	    lv_obj_align(s_money_pill, LV_ALIGN_TOP_MID, 0, 30);
498	
499	    lv_obj_t *money_caption = lv_label_create(s_money_pill);
500	    lv_obj_set_style_text_font(money_caption, &lv_font_montserrat_14, LV_PART_MAIN | LV_STATE_DEFAULT);
501	    lv_obj_set_style_text_color(money_caption, lv_color_hex(AI_MONEY_COLOR_TEXT), LV_PART_MAIN | LV_STATE_DEFAULT);
502	    lv_label_set_text(money_caption, "You save:");
503	
504	    s_money_lbl = lv_label_create(s_money_pill);
505	    lv_obj_set_style_text_font(s_money_lbl, &lv_font_montserrat_24, LV_PART_MAIN | LV_STATE_DEFAULT);
506	    lv_obj_set_style_text_color(s_money_lbl, lv_color_hex(AI_MONEY_COLOR_TEXT), LV_PART_MAIN | LV_STATE_DEFAULT);
507	    lv_label_set_text(s_money_lbl, "-- PLN");
508	
509	    // Right half: the orchard (long-term driving history). Trees sit at fixed
510	    // scattered spots directly on the meadow background — no grid.
511	    lv_obj_t *right = lv_obj_create(parent);
512	    lv_obj_remove_style_all(right);
513	    lv_obj_add_flag(right, LV_OBJ_FLAG_IGNORE_LAYOUT);
514	    lv_obj_clear_flag(right, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
515	    lv_obj_set_size(right, LV_PCT(50), LV_PCT(100));
516	    lv_obj_align(right, LV_ALIGN_RIGHT_MID, 0, 0);
517	
518	    // Painter's order: create back-to-front (ascending y) so a tree lower on
519	    // the screen overlaps the ones behind it, regardless of harvest order.
520	    uint32_t order[AI_ORCHARD_SLOTS];
521	    for (uint32_t i = 0; i < AI_ORCHARD_SLOTS; i++) order[i] = i;
522	    for (uint32_t i = 1; i < AI_ORCHARD_SLOTS; i++) {
523	        uint32_t key = order[i];
524	        uint32_t j = i;
525	        while (j > 0 && s_orchard_spots[order[j - 1]].y > s_orchard_spots[key].y) {
526	            order[j] = order[j - 1];
527	            j--;
528	        }
529	        order[j] = key;
530	    }
531	
532	    for (uint32_t k = 0; k < AI_ORCHARD_SLOTS; k++) {
533	        uint32_t slot = order[k];
534	        lv_obj_t *img = lv_img_create(right);
535	        lv_obj_clear_flag(img, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
536	        // Pre-scaled asset — no runtime zoom (LV_IMG_SIZE_MODE_REAL
537	        // rendering proved unreliable on this LVGL version).
538	        lv_img_set_src(img, &eco_tree_orchard);
539	        lv_obj_set_pos(img, s_orchard_spots[slot].x, s_orchard_spots[slot].y);
540	        lv_obj_add_flag(img, LV_OBJ_FLAG_HIDDEN);
541	        s_orchard_imgs[slot] = img;
542	    }
543	
544	    // Edge glow: stacked transparent full-screen overlays, only their borders
545	    // are drawn. Widths/opacities approximate a blurred glow along the screen
546	    // perimeter. Parented to the tab page (zero padding), not container_can_1
547	    // (pad_top 12), so the glow hugs all four screen edges. Created last so
548	    // they sit on top.
549	    lv_obj_t *glow_parent = (objects.tab_ai != NULL) ? objects.tab_ai : parent;
550	    for (int i = 0; i < AI_GLOW_LAYERS; i++) {
551	        lv_obj_t *obj = lv_obj_create(glow_parent);
552	        lv_obj_remove_style_all(obj);
553	        lv_obj_add_flag(obj, LV_OBJ_FLAG_IGNORE_LAYOUT | LV_OBJ_FLAG_HIDDEN);
554	        lv_obj_clear_flag(obj, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
555	        lv_obj_set_size(obj, LV_PCT(100), LV_PCT(100));
556	        lv_obj_align(obj, LV_ALIGN_CENTER, 0, 0);
557	        lv_obj_set_style_border_width(obj, s_glow_width[i], LV_PART_MAIN | LV_STATE_DEFAULT);
558	        lv_obj_set_style_border_opa(obj, s_glow_opa[i], LV_PART_MAIN | LV_STATE_DEFAULT);
559	        s_glow_layers[i] = obj;
560	    }
561	}
