563	// Show the screen-edge glow in the driving-style color (hidden for NORMAL).
564	static void ai_glow_update(const ai_model_snapshot_t *snap)
565	{
566	    if (s_glow_layers[0] == NULL) return;
567	
568	    bool visible = snap->ready && snap->style != AI_DRIVING_STYLE_NORMAL;
569	    lv_color_t color = lv_color_hex(snap->style == AI_DRIVING_STYLE_AGGRESSIVE
570	                                        ? AI_TAB_COLOR_AGGRESSIVE_MAX
571	                                        : AI_TAB_COLOR_ECO_MAX);
572	
573	    for (int i = 0; i < AI_GLOW_LAYERS; i++) {
574	        if (visible) {
575	            lv_obj_set_style_border_color(s_glow_layers[i], color, LV_PART_MAIN | LV_STATE_DEFAULT);
576	            lv_obj_clear_flag(s_glow_layers[i], LV_OBJ_FLAG_HIDDEN);
577	        } else {
578	            lv_obj_add_flag(s_glow_layers[i], LV_OBJ_FLAG_HIDDEN);
579	        }
580	    }
581	}
