583	// Sync the orchard grid with the current count.
584	static void ai_orchard_update(void)
585	{
586	    if (s_orchard_imgs[0] == NULL) return;
587	
588	    uint32_t cnt = s_orchard_count;
589	    if (cnt == s_orchard_shown) return;
590	    s_orchard_shown = cnt;
591	    ESP_LOGI(TAG, "Orchard render: %lu trees", (unsigned long)cnt);
592	
593	    uint32_t shown = cnt < AI_ORCHARD_SLOTS ? cnt : AI_ORCHARD_SLOTS;
594	    for (uint32_t i = 0; i < AI_ORCHARD_SLOTS; i++) {
595	        if (i < shown) {
596	            lv_obj_clear_flag(s_orchard_imgs[i], LV_OBJ_FLAG_HIDDEN);
597	        } else {
598	            lv_obj_add_flag(s_orchard_imgs[i], LV_OBJ_FLAG_HIDDEN);
599	        }
600	    }
601	}
