613	// Pop a "+n zl" coin out from the right side of the money pill: hops up,
614	// settles back down, then fades out and deletes itself (lv_obj_del cancels
615	// any still-running move anim too).
616	static void ai_money_spawn_coin(int gr_delta)
617	{
618	    if (s_money_pill == NULL || gr_delta <= 0) return;
619	
620	    // Spawn on the full-width canvas (the pill's grandparent), not the
621	    // half-width "left" pane the pill lives in — otherwise a coin drifting
622	    // out to the right gets clipped off entirely by that pane's edge.
623	    lv_obj_t *pill_pane = lv_obj_get_parent(s_money_pill);
624	    lv_obj_t *parent = lv_obj_get_parent(pill_pane);
625	    // Two-tone coin: a bronze "rim" ring wrapping a smaller gold "face" —
626	    // the rim is just the outer circle's padding showing through around the
627	    // inner one, no extra layout math needed.
628	    lv_obj_t *coin = lv_obj_create(parent);
629	    lv_obj_remove_style_all(coin);
630	    lv_obj_add_flag(coin, LV_OBJ_FLAG_IGNORE_LAYOUT);
631	    lv_obj_clear_flag(coin, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
632	    lv_obj_set_size(coin, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
633	    lv_obj_set_style_bg_color(coin, lv_color_hex(AI_COIN_COLOR_RIM), LV_PART_MAIN | LV_STATE_DEFAULT);
634	    lv_obj_set_style_bg_opa(coin, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
635	    lv_obj_set_style_border_color(coin, lv_color_hex(AI_TAB_COLOR_ECO_MAX), LV_PART_MAIN | LV_STATE_DEFAULT);
636	    lv_obj_set_style_border_width(coin, 2, LV_PART_MAIN | LV_STATE_DEFAULT);
637	    lv_obj_set_style_radius(coin, LV_RADIUS_CIRCLE, LV_PART_MAIN | LV_STATE_DEFAULT);
638	    lv_obj_set_style_pad_all(coin, 4, LV_PART_MAIN | LV_STATE_DEFAULT);
639	
640	    lv_obj_t *face = lv_obj_create(coin);
641	    lv_obj_remove_style_all(face);
642	    lv_obj_clear_flag(face, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
643	    lv_obj_set_size(face, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
644	    lv_obj_set_style_bg_color(face, lv_color_hex(AI_COIN_COLOR_FACE), LV_PART_MAIN | LV_STATE_DEFAULT);
645	    lv_obj_set_style_bg_opa(face, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
646	    lv_obj_set_style_radius(face, LV_RADIUS_CIRCLE, LV_PART_MAIN | LV_STATE_DEFAULT);
647	    lv_obj_set_style_pad_hor(face, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
648	    lv_obj_set_style_pad_ver(face, 5, LV_PART_MAIN | LV_STATE_DEFAULT);
649	
650	    lv_obj_t *lbl = lv_label_create(face);
651	    lv_obj_set_style_text_font(lbl, &lv_font_montserrat_20, LV_PART_MAIN | LV_STATE_DEFAULT);
652	    lv_obj_set_style_text_color(lbl, lv_color_hex(AI_MONEY_COLOR_TEXT), LV_PART_MAIN | LV_STATE_DEFAULT);
653	    // Plain "zl": built-in Montserrat only ships basic Latin, no Polish
654	    // diacritics (same reason the STATS page spells it out as "PLN").
655	    lv_label_set_text_fmt(lbl, "+%d.%02d zl", gr_delta / 100, gr_delta % 100);
656	    lv_obj_center(lbl);
657	
658	    lv_obj_align_to(coin, s_money_pill, LV_ALIGN_OUT_RIGHT_MID, 8, 10);
659	    // align_to only sets the x/y style props and marks the layout dirty; the
660	    // object's actual coords aren't recomputed until the next layout pass.
661	    // Force that pass now so lv_obj_get_y() below reads the real position
662	    // instead of the stale (0,0) from creation.
663	    lv_obj_update_layout(coin);
664	    lv_coord_t y0 = lv_obj_get_y(coin);
665	    ESP_LOGI(TAG, "Coin spawned: parent=%p pos=(%d,%d) size=(%d,%d)",
666	             (void *)parent, (int)lv_obj_get_x(coin), (int)y0,
667	             (int)lv_obj_get_width(coin), (int)lv_obj_get_height(coin));
668	
669	    // Two-leg vertical flight: a quick hop up, then settling back down a bit,
670	    // like a tossed coin — slower overall than a straight rise.
671	    uint32_t up_time   = (AI_COIN_ANIM_TIME_MS * 4) / 10;
672	    uint32_t down_time = AI_COIN_ANIM_TIME_MS - up_time;
673	
674	    lv_anim_t a_up;
675	    lv_anim_init(&a_up);
676	    lv_anim_set_var(&a_up, coin);
677	    lv_anim_set_values(&a_up, y0, y0 - AI_COIN_ANIM_RISE_PX);
678	    lv_anim_set_time(&a_up, up_time);
679	    lv_anim_set_exec_cb(&a_up, (lv_anim_exec_xcb_t)lv_obj_set_y);
680	    lv_anim_set_path_cb(&a_up, lv_anim_path_ease_out);
681	    lv_anim_start(&a_up);
682	
683	    lv_anim_t a_down;
684	    lv_anim_init(&a_down);
685	    lv_anim_set_var(&a_down, coin);
686	    lv_anim_set_values(&a_down, y0 - AI_COIN_ANIM_RISE_PX,
687	                       y0 - AI_COIN_ANIM_RISE_PX + AI_COIN_ANIM_FALL_PX);
688	    lv_anim_set_time(&a_down, down_time);
689	    lv_anim_set_delay(&a_down, up_time);
690	    lv_anim_set_exec_cb(&a_down, (lv_anim_exec_xcb_t)lv_obj_set_y);
691	    lv_anim_set_path_cb(&a_down, lv_anim_path_ease_in);
692	    lv_anim_start(&a_down);
693	
694	    lv_anim_t a_fade;
695	    lv_anim_init(&a_fade);
696	    lv_anim_set_var(&a_fade, coin);
697	    lv_anim_set_values(&a_fade, LV_OPA_COVER, LV_OPA_TRANSP);
698	    lv_anim_set_time(&a_fade, AI_COIN_ANIM_TIME_MS / 2);
699	    lv_anim_set_delay(&a_fade, AI_COIN_ANIM_TIME_MS / 2);
700	    lv_anim_set_exec_cb(&a_fade, ai_coin_set_opa_cb);
701	    lv_anim_set_ready_cb(&a_fade, ai_coin_anim_del_cb);
702	    lv_anim_start(&a_fade);
703	}
704	
705	// Refresh the trip-savings pill and pop a coin for every AI_MONEY_COIN_STEP_GR
706	// crossed since the last tick (usually one step, but a UI hiccup could skip
707	// several).
708	static void ai_money_update(void)
709	{
710	    if (s_money_lbl == NULL) return;
711	
712	    bool calibrated = false;
713	    int32_t gr = eco_stats_get_trip_saved_gr(&calibrated);
714	    if (gr == s_money_shown_gr) return;
715	    s_money_shown_gr = gr;
716	
717	    if (!calibrated) {
718	        lv_label_set_text(s_money_lbl, "-- PLN");
719	        return;
720	    }
721	    lv_label_set_text_fmt(s_money_lbl, "%ld.%02ld PLN", (long)(gr / 100), (long)(gr % 100));
722	
723	    int32_t step_now = gr / AI_MONEY_COIN_STEP_GR;
724	    if (step_now > s_money_last_step) {
725	        ESP_LOGI(TAG, "Money step crossed: gr=%ld step %ld->%ld, spawning coin",
726	                 (long)gr, (long)s_money_last_step, (long)step_now);
727	        ai_money_spawn_coin((int)((step_now - s_money_last_step) * AI_MONEY_COIN_STEP_GR));
728	    }
729	    s_money_last_step = step_now;
730	}
731	
732	static void ai_tree_update(int32_t score, bool withered)
733	{
734	    ai_tree_ensure_created();
735	    if (s_tree_img == NULL) return;
736	
737	    int stage = ai_tree_stage_from_state(score, withered);
738	    if (stage != s_tree_stage) {
739	        s_tree_stage = stage;
740	        lv_img_set_src(s_tree_img, eco_tree_stages[stage]);
741	    }
742	}
743	
744	void ai_model_update_ui_locked(void)
745	{
746	    ai_model_snapshot_t snap;
747	    ai_model_get_snapshot(&snap);
748	
749	    // Eco-tree grows/withers with the driving style.
750	    ai_tree_update(snap.score, s_withered);
751	    ai_orchard_update();
752	    ai_glow_update(&snap);
753	    ai_money_update();
754	
755	    // Tint the CAN page background with the current driving style (the AI page
756	    // is covered by the meadow image; its feedback is the tree + edge glow).
757	    if (objects.container_can != NULL) {
758	        if (!s_tab_color_init) {
759	            s_tab_neutral_color = lv_obj_get_style_bg_color(
760	                objects.container_can, LV_PART_MAIN | LV_STATE_DEFAULT
761	            );
762	            s_tab_color_init = true;
763	        }
764	        lv_color_t tab_color;
765	        if (!snap.ready || snap.style == AI_DRIVING_STYLE_NORMAL) {
766	            tab_color = s_tab_neutral_color;
767	        } else if (snap.style == AI_DRIVING_STYLE_AGGRESSIVE) {
768	            tab_color = lv_color_hex(AI_TAB_COLOR_AGGRESSIVE_MAX);
769	        } else {
770	            tab_color = lv_color_hex(AI_TAB_COLOR_ECO_MAX);
771	        }
772	        lv_obj_set_style_bg_color(
773	            objects.container_can,
774	            tab_color,
775	            LV_PART_MAIN | LV_STATE_DEFAULT
776	        );
777	    }
778	}
