% Schemat blokowy architektury systemu — edytowalny rysunek TikZ.
% Układ: pojazd (góra) -> urządzenie pokładowe (środek) -> środowisko
% treningowe (dół, pętla rozwoju modelu zaznaczona liniami przerywanymi).
\begin{tikzpicture}[
    font=\scriptsize,
    block/.style={draw, rounded corners=2pt, align=center, fill=white,
                  text width=2.4cm, minimum height=8mm, inner sep=3pt},
    wide/.style ={draw, rounded corners=2pt, align=center, fill=white,
                  minimum height=9mm, inner sep=4pt},
    store/.style={draw, align=center, fill=black!10,
                  text width=2.4cm, minimum height=8mm, inner sep=3pt},
    aux/.style  ={draw, align=center, fill=black!8, font=\tiny,
                  text width=2.4cm, minimum height=6mm, inner sep=2pt},
    cont/.style ={draw, rounded corners=4pt, fill=black!3, inner sep=7pt},
    title/.style={fill=white, font=\bfseries\scriptsize, inner sep=2pt},
    arr/.style  ={-{Stealth[length=2.2mm]}, semithick},
    dev/.style  ={-{Stealth[length=2.2mm]}, semithick, dashed}
]
    % ---- Pojazd ----------------------------------------------------------
    \node[block] (ecu) at (0,2.8)   {jednostki sterujące (ECU)};
    \node[block] (can) at (3.4,2.8) {magistrala CAN};

    % ---- Urządzenie: wiersz 1 (akwizycja) --------------------------------
    \node[block] (parser)  at (0,0)    {parser i walidacja ramek};
    \node[block] (stan)    at (4.65,0) {bieżący stan pojazdu};
    \node[block] (sampler) at (9.3,0)  {zadanie próbkujące (10~Hz)};

    % ---- wiersz 2: rejestracja + początek inferencji ---------------------
    \node[block] (rej)   at (0,-1.8)   {rejestrator (pliki CSV)};
    \node[block] (kwant) at (3.1,-1.8) {kwantyzacja cech (int16)};
    \node[block] (cechy) at (6.2,-1.8) {ekstrakcja 20~cech};
    \node[block] (okno)  at (9.3,-1.8) {okno przesuwne 5~s (50~próbek)};

    % ---- wiersz 3: klasyfikacja i prezentacja ----------------------------
    \node[store]                (karta) at (0,-3.6)   {karta SD};
    \node[block, fill=blue!10]  (model) at (3.1,-3.6)  {model drzewiasty (klasyfikator)};
    \node[block]                (score) at (6.2,-3.6)  {punktacja i~grywalizacja};
    \node[block, fill=green!10] (ui)    at (9.3,-3.6)  {interfejs graficzny (LVGL)};

    % ---- moduły pomocnicze ------------------------------------------------
    \node[aux] (rtc) at (3.1,-5.1) {RTC / NTP (znakowanie czasem)};
    \node[aux] (nvs) at (6.2,-5.1) {NVS (pamięć trwała)};
    \node[aux] (pwr) at (9.3,-5.1) {zarządzanie energią (głębokie uśpienie)};

    % ---- środowisko treningowe --------------------------------------------
    \node[wide, text width=4.4cm] (pc) at (1.5,-7.2)
        {komputer PC: przygotowanie danych, trening i~walidacja modeli};
    \node[wide, text width=3.0cm] (eksport) at (7.0,-7.2)
        {eksport emlearn (nagłówki~C)};

    % ---- kontenery ----------------------------------------------------------
    \begin{scope}[on background layer]
        \node[cont] (vehicle) [fit=(ecu)(can)] {};
        \node[cont] (device)  [fit=(parser)(sampler)(rej)(okno)(karta)(ui)(rtc)(nvs)(pwr)] {};
        \node[cont, dashed] (train) [fit=(pc)(eksport)] {};
    \end{scope}
    \node[title] at (vehicle.north) {POJAZD};
    \node[title] at (device.north)  {URZĄDZENIE POKŁADOWE (ESP32-S3)};
    \node[title] at (train.north)   {ŚRODOWISKO TRENINGOWE (offline)};

    % ---- przepływ danych ----------------------------------------------------
    \draw[arr] (ecu) -- (can);
    \coordinate (v1) at ($(can.south)+(0,-0.55)$);
    \draw[arr] (can.south) -- (v1) -- (v1 -| parser.north)
        node[midway, above, font=\tiny] {ramki CAN (tylko nasłuch)}
        -- (parser.north);
    \draw[arr] (parser) -- (stan);
    \draw[arr] (stan) -- (sampler);
    \draw[arr] (sampler) -- (okno);
    \draw[arr] ($(sampler.south)+(0,-0.5)$) -| (rej.north);
    \draw[arr] (rej) -- (karta);
    \draw[arr] (okno) -- (cechy);
    \draw[arr] (cechy) -- (kwant);
    \draw[arr] (kwant) -- (model);
    \draw[arr] (model) -- (score) node[midway, above, font=\tiny] {klasa stylu};
    \draw[arr] (score) -- (ui);

    % ---- pętla rozwoju modelu (offline) --------------------------------------
    \draw[dev] (karta.south) -| (pc.north)
        node[pos=0.75, right, font=\tiny] {nagrania przejazdów};
    \draw[dev] (pc) -- (eksport);
    \coordinate (rx) at ($(device.east)+(0.6,0)$);
    \draw[dev] (eksport.east) -- (eksport.east -| rx)
        -- (rx) node[midway, rotate=90, above, font=\tiny] {wbudowanie modelu (kompilacja)}
        -- (device.east);
\end{tikzpicture}

