68	bool rtc_manager_time_is_valid(const struct tm *timeinfo)
69	{
70	    if (timeinfo == NULL) {
71	        return false;
72	    }
73	
74	    int year = timeinfo->tm_year + 1900;
75	    return year >= 2024 && year <= 2099 &&
76	           timeinfo->tm_mon >= 0 && timeinfo->tm_mon < 12 &&
77	           timeinfo->tm_mday >= 1 && timeinfo->tm_mday <= 31 &&
78	           timeinfo->tm_hour >= 0 && timeinfo->tm_hour < 24 &&
79	           timeinfo->tm_min >= 0 && timeinfo->tm_min < 60 &&
80	           timeinfo->tm_sec >= 0 && timeinfo->tm_sec < 60;
81	}
