83	esp_err_t rtc_manager_read_time(struct tm *timeinfo)
84	{
85	    if (!s_initialized) {
86	        return ESP_ERR_INVALID_STATE;
87	    }
88	
89	    if (timeinfo == NULL) {
90	        return ESP_ERR_INVALID_ARG;
91	    }
92	
93	    uint8_t data[7] = {0};
94	    esp_err_t ret = rtc_read_bytes(RTC_SECOND_ADDR, data, sizeof(data));
95	    if (ret != ESP_OK) {
96	        return ret;
97	    }
98	
99	    memset(timeinfo, 0, sizeof(*timeinfo));
100	    timeinfo->tm_sec = bcd_to_dec(data[0] & 0x7F);
101	    timeinfo->tm_min = bcd_to_dec(data[1] & 0x7F);
102	    timeinfo->tm_hour = bcd_to_dec(data[2] & 0x3F);
103	    timeinfo->tm_mday = bcd_to_dec(data[3] & 0x3F);
104	    timeinfo->tm_wday = bcd_to_dec(data[4] & 0x07);
105	    timeinfo->tm_mon = bcd_to_dec(data[5] & 0x1F) - 1;
106	    timeinfo->tm_year = bcd_to_dec(data[6]) + (YEAR_BASE - 1900);
107	    return ESP_OK;
108	}
109	
110	esp_err_t rtc_manager_write_time(const struct tm *timeinfo)
111	{
112	    if (!s_initialized) {
113	        return ESP_ERR_INVALID_STATE;
114	    }
115	
116	    if (!rtc_manager_time_is_valid(timeinfo)) {
117	        return ESP_ERR_INVALID_ARG;
118	    }
119	
120	    uint8_t data[7] = {
121	        dec_to_bcd(timeinfo->tm_sec),
122	        dec_to_bcd(timeinfo->tm_min),
123	        dec_to_bcd(timeinfo->tm_hour),
124	        dec_to_bcd(timeinfo->tm_mday),
125	        dec_to_bcd(timeinfo->tm_wday),
126	        dec_to_bcd(timeinfo->tm_mon + 1),
127	        dec_to_bcd((timeinfo->tm_year + 1900) - YEAR_BASE),
128	    };
129	
130	    return rtc_write_bytes(RTC_SECOND_ADDR, data, sizeof(data));
131	}
