133	esp_err_t rtc_manager_sync_system_from_rtc(void)
134	{
135	    struct tm timeinfo;
136	    esp_err_t ret = rtc_manager_read_time(&timeinfo);
137	    if (ret != ESP_OK) {
138	        return ret;
139	    }
140	
141	    if (!rtc_manager_time_is_valid(&timeinfo)) {
142	        return ESP_ERR_INVALID_STATE;
143	    }
144	
145	    // Let mktime determine DST based on configured TZ rules.
146	    timeinfo.tm_isdst = -1;
147	
148	    struct timeval tv = {
149	        .tv_sec = mktime(&timeinfo),
150	        .tv_usec = 0,
151	    };
152	
153	    if (tv.tv_sec < 0) {
154	        return ESP_FAIL;
155	    }
156	
157	    return settimeofday(&tv, NULL);
158	}
