99	    float    cal_normal_m;
100	    float    saved_fuel_l;
101	    int32_t  fuel_gr;           // fuel savings in grosze
102	    int32_t  wear_gr;           // maintenance savings in grosze (model)
103	    float    co2_kg;
104	    float    share[3];          // time share per style, 0..1
105	    float    dist_km;           // total classified distance in scope
106	    uint32_t harvested, withered, streak_best;
107	    float    trees_per_100km;
108	} eco_stats_view_t;
109	
110	static float safe_rate(float num, float den)
111	{
112	    return (den > 0.0f) ? (num / den) : 0.0f;
113	}
114	
115	// Rates (l/100km, events/m) always come from lifetime accumulators — the
116	// calibrated model — and are applied to the eco distance of the chosen scope.
117	static void eco_stats_compute_view(bool lifetime, eco_stats_view_t *v)
118	{
119	    eco_stats_data_t life, scope;
120	
121	    portENTER_CRITICAL(&s_lock);
122	    life = s_life;
123	    scope = lifetime ? s_life : s_trip;
124	    portEXIT_CRITICAL(&s_lock);
125	
126	    memset(v, 0, sizeof(*v));
127	    v->cal_eco_m    = life.dist_m[AI_DRIVING_STYLE_ECO];
128	    v->cal_normal_m = life.dist_m[AI_DRIVING_STYLE_NORMAL];
129	    v->calibrated   = v->cal_eco_m >= ECO_CAL_MIN_DIST_M &&
130	                      v->cal_normal_m >= ECO_CAL_MIN_DIST_M;
131	
132	    float time_total = scope.time_s[0] + scope.time_s[1] + scope.time_s[2];
133	    for (int i = 0; i < 3; i++) v->share[i] = safe_rate(scope.time_s[i], time_total);
134	
135	    float dist_total = scope.dist_m[0] + scope.dist_m[1] + scope.dist_m[2];
136	    v->dist_km = dist_total / 1000.0f;
137	
138	    v->harvested   = scope.trees_harvested;
139	    v->withered    = scope.trees_withered;
140	    v->streak_best = life.streak_best;  // streak only makes sense lifetime
141	    v->trees_per_100km = safe_rate((float)scope.trees_harvested, dist_total / 100000.0f);
142	
143	    if (!v->calibrated) return;
144	
145	    float eco_dist_m = scope.dist_m[AI_DRIVING_STYLE_ECO];
146	
147	    // Fuel: liters per 100 km = fuel_ml * 100 / dist_m
148	    float l100_eco    = safe_rate(life.fuel_ml[AI_DRIVING_STYLE_ECO] * 100.0f,
149	                                  life.dist_m[AI_DRIVING_STYLE_ECO]);
150	    float l100_normal = safe_rate(life.fuel_ml[AI_DRIVING_STYLE_NORMAL] * 100.0f,
151	                                  life.dist_m[AI_DRIVING_STYLE_NORMAL]);
152	    float dl100 = l100_normal - l100_eco;
153	    if (dl100 < 0.0f) dl100 = 0.0f;
154	    v->saved_fuel_l = (eco_dist_m / 100000.0f) * dl100;
155	    v->fuel_gr = (int32_t)(v->saved_fuel_l * (float)s_price_gr);
156	    v->co2_kg  = v->saved_fuel_l * ECO_CO2_G_PER_L / 1000.0f;
157	
158	    // Maintenance: avoided events = eco distance x (non-eco rate - eco rate),
159	    // rates per meter from lifetime data. Clamped at zero per component.
160	    float noneco_dist = life.dist_m[AI_DRIVING_STYLE_NORMAL] +
161	                        life.dist_m[AI_DRIVING_STYLE_AGGRESSIVE];
162	    float brakes_noneco = (float)(life.hard_brakes[AI_DRIVING_STYLE_NORMAL] +
163	                                  life.hard_brakes[AI_DRIVING_STYLE_AGGRESSIVE]);
164	    float accels_noneco = (float)(life.harsh_accels[AI_DRIVING_STYLE_NORMAL] +
165	                                  life.harsh_accels[AI_DRIVING_STYLE_AGGRESSIVE]);
166	    float rpm_noneco    = life.high_rpm_s[AI_DRIVING_STYLE_NORMAL] +
167	                          life.high_rpm_s[AI_DRIVING_STYLE_AGGRESSIVE];
168	
169	    float d_brakes = safe_rate(brakes_noneco, noneco_dist) -
170	                     safe_rate((float)life.hard_brakes[AI_DRIVING_STYLE_ECO],
171	                               life.dist_m[AI_DRIVING_STYLE_ECO]);
172	    float d_accels = safe_rate(accels_noneco, noneco_dist) -
173	                     safe_rate((float)life.harsh_accels[AI_DRIVING_STYLE_ECO],
174	                               life.dist_m[AI_DRIVING_STYLE_ECO]);
175	    float d_rpm_s  = safe_rate(rpm_noneco, noneco_dist) -
176	                     safe_rate(life.high_rpm_s[AI_DRIVING_STYLE_ECO],
177	                               life.dist_m[AI_DRIVING_STYLE_ECO]);
178	    if (d_brakes < 0.0f) d_brakes = 0.0f;
179	    if (d_accels < 0.0f) d_accels = 0.0f;
180	    if (d_rpm_s  < 0.0f) d_rpm_s  = 0.0f;
181	
182	    v->wear_gr = (int32_t)(eco_dist_m * d_brakes * ECO_COST_HARD_BRAKE_GR +
183	                           eco_dist_m * d_accels * ECO_COST_HARSH_ACCEL_GR +
184	                           eco_dist_m * d_rpm_s / 60.0f * ECO_COST_HIGHRPM_GR_PER_MIN);
185	}
