189	static void eco_stats_nvs_load(void)
190	{
191	    nvs_handle_t handle;
192	    if (nvs_open(ECO_NVS_NAMESPACE, NVS_READONLY, &handle) != ESP_OK) return;
193	
194	    eco_stats_data_t blob;
195	    size_t len = sizeof(blob);
196	    if (nvs_get_blob(handle, ECO_NVS_KEY_BLOB, &blob, &len) == ESP_OK &&
197	        len == sizeof(blob) && blob.version == ECO_STATS_VERSION) {
198	        s_life = blob;
199	    }
200	    uint16_t price;
201	    if (nvs_get_u16(handle, ECO_NVS_KEY_PRICE, &price) == ESP_OK &&
202	        price >= ECO_PRICE_MIN_GR && price <= ECO_PRICE_MAX_GR) {
203	        s_price_gr = price;
204	    }
205	    nvs_close(handle);
206	}
207	
208	void eco_stats_flush(void)
209	{
210	    eco_stats_data_t copy;
211	    portENTER_CRITICAL(&s_lock);
212	    copy = s_life;
213	    s_dirty = false;
214	    portEXIT_CRITICAL(&s_lock);
215	
216	    nvs_handle_t handle;
217	    if (nvs_open(ECO_NVS_NAMESPACE, NVS_READWRITE, &handle) != ESP_OK) {
218	        ESP_LOGW(TAG, "Failed to open NVS for stats save");
219	        return;
220	    }
221	    if (nvs_set_blob(handle, ECO_NVS_KEY_BLOB, &copy, sizeof(copy)) == ESP_OK) {
222	        nvs_commit(handle);
223	    }
224	    nvs_close(handle);
225	}
