231	    memset(&s_life, 0, sizeof(s_life));
232	    memset(&s_trip, 0, sizeof(s_trip));
233	    s_life.version = version;
234	    s_trip.version = version;
235	    portEXIT_CRITICAL(&s_lock);
236	
237	    eco_stats_flush();
238	    eco_stats_update_ui_locked();
239	}
