266	    s_trip.trees_harvested++;
267	    s_life.streak_cur++;
268	    if (s_life.streak_cur > s_life.streak_best) s_life.streak_best = s_life.streak_cur;
269	    portEXIT_CRITICAL(&s_lock);
270	    s_dirty = true;
271	}
