275	    portENTER_CRITICAL(&s_lock);
276	    s_life.trees_withered++;
277	    s_trip.trees_withered++;
278	    s_life.streak_cur = 0;
279	    portEXIT_CRITICAL(&s_lock);
280	    s_dirty = true;
281	}
282	
283	void eco_stats_process_sample(const can_data_t *data)
284	{
285	    if (data == NULL) return;
286	
287	    // The logger task re-reads the same snapshot when the bus is quiet; only a
288	    // fresh CAN timestamp carries new information. Backward jump = re-anchor.
289	    if (data->timestamp == s_last_ts) return;
290	    if (data->timestamp < s_last_ts) {
291	        s_last_ts = data->timestamp;
292	        s_fuel_anchored = false;
293	        return;
294	    }
295	
296	    float real_dt = 0.1f;
297	    if (s_last_ts > 0) {
298	        real_dt = (float)(data->timestamp - s_last_ts) / 1000.0f;
299	        if (real_dt < 0.01f) real_dt = 0.01f;
300	    }
301	    s_last_ts = data->timestamp;
302	    bool gap = real_dt > 2.0f;           // bus silence: don't fake dynamics across it
303	    float dt_s = (real_dt > 1.0f) ? 1.0f : real_dt;  // nor attribute a big blob
304	
305	    float spd_ms = (float)data->speed / 3.6f;
306	    float accel  = gap ? 0.0f : (spd_ms - s_last_spd_ms) / dt_s;
307	    s_last_spd_ms = spd_ms;
308	
309	    // Fuel counter is cumulative ml and user-resettable; a negative delta or an
310	    // implausible spike (>50 ml per sample = 1800 l/h) means reset/glitch.
311	    float dfuel = 0.0f;
312	    if (s_fuel_anchored) {
313	        dfuel = data->fuel_consumption - s_last_fuel_ml;
314	        if (dfuel < 0.0f || dfuel > 50.0f) dfuel = 0.0f;
315	    }
316	    s_last_fuel_ml = data->fuel_consumption;
317	    s_fuel_anchored = true;
318	
319	    ai_model_snapshot_t snap;
320	    ai_model_get_snapshot(&snap);
321	
322	    // Same gate as the training-data filters in ai_model_process_sample().
323	    bool classified = data->ignition && !data->rear_gear && data->speed >= 2 &&
324	                      snap.ready && snap.style <= AI_DRIVING_STYLE_AGGRESSIVE;
325	
326	    portENTER_CRITICAL(&s_lock);
327	    if (classified) {
328	        int b = (int)snap.style;
329	        float dm = spd_ms * dt_s;
330	        s_life.dist_m[b] += dm;           s_trip.dist_m[b] += dm;
331	        s_life.time_s[b] += dt_s;         s_trip.time_s[b] += dt_s;
332	        s_life.fuel_ml[b] += dfuel;       s_trip.fuel_ml[b] += dfuel;
333	        if (data->rpm > ECO_HIGH_RPM) {
334	            s_life.high_rpm_s[b] += dt_s; s_trip.high_rpm_s[b] += dt_s;
335	        }
336	
337	        if (!s_brake_latched && accel <= ECO_HARD_BRAKE_MS2) {
338	            s_brake_latched = true;
339	            s_life.hard_brakes[b]++;      s_trip.hard_brakes[b]++;
340	        } else if (s_brake_latched && accel >= ECO_HARD_BRAKE_RELEASE_MS2) {
341	            s_brake_latched = false;
342	        }
343	        if (!s_accel_latched && accel >= ECO_HARSH_ACCEL_MS2) {
344	            s_accel_latched = true;
345	            s_life.harsh_accels[b]++;     s_trip.harsh_accels[b]++;
346	        } else if (s_accel_latched && accel <= ECO_HARSH_ACCEL_RELEASE_MS2) {
347	            s_accel_latched = false;
348	        }
349	        s_dirty = true;
350	    } else {
351	        if (data->ignition && dfuel > 0.0f) {
352	            s_life.idle_fuel_ml += dfuel; s_trip.idle_fuel_ml += dfuel;
353	            s_dirty = true;
354	        }
355	        s_brake_latched = false;
356	        s_accel_latched = false;
357	    }
358	    portEXIT_CRITICAL(&s_lock);
359	
360	    // Persist on ignition-off and periodically while dirty (flash-friendly).
361	    bool ignition_off_edge = (s_last_ignition && !data->ignition);
362	    s_last_ignition = data->ignition;
363	    s_save_timer_s += dt_s;
364	    if ((ignition_off_edge || s_save_timer_s >= ECO_NVS_SAVE_PERIOD_S) && s_dirty) {
365	        s_save_timer_s = 0.0f;
366	        eco_stats_flush();
367	    }
368	}
