49	// Screen "brightness": the backlight pin sits on the CH422G I2C expander
50	// (on/off only, no PWM), so dimming is simulated with a black overlay on the
51	// LVGL top layer whose opacity grows as brightness drops. The overlay is not
52	// clickable, so touches pass through. Range 20-100% keeps the screen readable.
53	#define UI_BRIGHTNESS_MIN     20
54	#define UI_BRIGHTNESS_MAX     100
55	#define UI_BRIGHTNESS_NVS_NS  "storage"
56	#define UI_BRIGHTNESS_NVS_KEY "brightness"
57	
58	static lv_obj_t *s_dim_overlay = NULL;
59	
60	static void apply_brightness(int32_t percent) {
61	    if (percent < UI_BRIGHTNESS_MIN) percent = UI_BRIGHTNESS_MIN;
62	    if (percent > UI_BRIGHTNESS_MAX) percent = UI_BRIGHTNESS_MAX;
63	
64	    if (s_dim_overlay == NULL) {
65	        s_dim_overlay = lv_obj_create(lv_layer_top());
66	        lv_obj_remove_style_all(s_dim_overlay);
67	        lv_obj_clear_flag(s_dim_overlay, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
68	        lv_obj_set_size(s_dim_overlay, LV_PCT(100), LV_PCT(100));
69	        lv_obj_set_style_bg_color(s_dim_overlay, lv_color_black(), LV_PART_MAIN | LV_STATE_DEFAULT);
70	    }
71	
72	    lv_opa_t opa = (lv_opa_t)((UI_BRIGHTNESS_MAX - percent) * 255 / UI_BRIGHTNESS_MAX);
73	    if (opa == 0) {
74	        lv_obj_add_flag(s_dim_overlay, LV_OBJ_FLAG_HIDDEN);
75	    } else {
76	        lv_obj_set_style_bg_opa(s_dim_overlay, opa, LV_PART_MAIN | LV_STATE_DEFAULT);
77	        lv_obj_clear_flag(s_dim_overlay, LV_OBJ_FLAG_HIDDEN);
78	    }
79	}
