81	// Keep the LVGL FPS/CPU monitor off the AI page (clean scene) but visible on
82	// the other pages. The monitor is a plain label LVGL creates lazily on the
83	// system layer at the first refresh, so it is looked up on demand; until it
84	// exists this is a no-op and ui_save_tick() retries periodically.
85	static void update_perf_monitor_visibility(void) {
86	    if (objects.tabview_main == NULL) {
87	        return;
88	    }
89	
90	    lv_obj_t *label = NULL;
91	    lv_obj_t *sys = lv_layer_sys();
92	    for (uint32_t i = 0; i < lv_obj_get_child_cnt(sys); i++) {
93	        lv_obj_t *child = lv_obj_get_child(sys, i);
94	        if (lv_obj_check_type(child, &lv_label_class)) {
95	            label = child;
96	            break;
97	        }
98	    }
99	    if (label == NULL) {
100	        return;
101	    }
102	
103	    uint32_t act = lv_tabview_get_tab_act(objects.tabview_main);
104	    lv_obj_t *page = lv_obj_get_child(lv_tabview_get_content(objects.tabview_main), act);
105	    if (page == objects.tab_ai || page == eco_stats_get_page()) {
106	        lv_obj_add_flag(label, LV_OBJ_FLAG_HIDDEN);
107	    } else {
108	        lv_obj_clear_flag(label, LV_OBJ_FLAG_HIDDEN);
109	    }
110	}
