112	static void update_page_dots(uint32_t active_idx) {
113	    for (uint32_t i = 0; i < s_page_dot_count; i++) {
114	        bool active = (i == active_idx);
115	        lv_obj_set_style_bg_color(s_page_dots[i],
116	            lv_color_hex(active ? 0xff333333 : 0xffb0b0b0), LV_PART_MAIN | LV_STATE_DEFAULT);
117	        lv_obj_set_size(s_page_dots[i], active ? 14 : 10, active ? 14 : 10);
118	    }
119	    update_perf_monitor_visibility();
120	}
