122	// Center text of all labels inside a tile (handles nested containers).
123	static void center_labels_recursive(lv_obj_t *obj) {
124	    if (lv_obj_check_type(obj, &lv_label_class)) {
125	        lv_obj_set_style_text_align(obj, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN | LV_STATE_DEFAULT);
126	        return;
127	    }
128	    for (uint32_t i = 0; i < lv_obj_get_child_cnt(obj); i++) {
129	        center_labels_recursive(lv_obj_get_child(obj, i));
130	    }
131	}
