138	// Swipe anywhere on the screen switches pages, wrapping around at both ends
139	// (last -> first and first -> last). Native content scrolling is disabled in
140	// ui_pager_init(), so gestures are the only page navigation.
141	static void screen_gesture_cb(lv_event_t *e) {
142	    LV_UNUSED(e);
143	
144	    lv_obj_t *tv = objects.tabview_main;
145	    if (tv == NULL) {
146	        return;
147	    }
148	
149	    // Don't flip pages while dragging horizontal controls (switch/slider).
150	    lv_indev_t *indev = lv_indev_get_act();
151	    lv_obj_t *pressed = lv_indev_get_obj_act();
152	    if (indev == NULL) {
153	        return;
154	    }
155	    if (pressed != NULL && (lv_obj_check_type(pressed, &lv_switch_class) ||
156	                            lv_obj_check_type(pressed, &lv_slider_class))) {
157	        return;
158	    }
159	
160	    uint32_t count = lv_obj_get_child_cnt(lv_tabview_get_content(tv));
161	    if (count < 2) {
162	        return;
163	    }
164	
165	    uint32_t act = lv_tabview_get_tab_act(tv);
166	    lv_dir_t dir = lv_indev_get_gesture_dir(indev);
167	    uint32_t next;
168	    if (dir == LV_DIR_LEFT) {
169	        next = (act + 1) % count;
170	    } else if (dir == LV_DIR_RIGHT) {
171	        next = (act + count - 1) % count;
172	    } else {
173	        return;
174	    }
175	
176	    lv_tabview_set_act(tv, next, LV_ANIM_ON);
177	    // lv_tabview_set_act() never emits VALUE_CHANGED (the tabview only sends
178	    // it for finger-scrolled page changes), so refresh the dots here.
179	    update_page_dots(next);
180	}
