182	void ui_pager_init(void) {
183	    lv_obj_t *tv = objects.tabview_main;
184	    if (tv == NULL) {
185	        return;
186	    }
187	
188	    // Hide tab button bar; tabview flex layout expands content to full screen.
189	    lv_obj_add_flag(lv_tabview_get_tab_btns(tv), LV_OBJ_FLAG_HIDDEN);
190	
191	    lv_obj_t *content = lv_tabview_get_content(tv);
192	
193	    // Loop-around paging: turn off the tabview's own swipe-scroll (it stops
194	    // dead at the first/last page) and drive page changes from full-screen
195	    // gestures instead — see screen_gesture_cb(). Programmatic
196	    // lv_tabview_set_act() still animates via lv_obj_scroll_to_x().
197	    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLLABLE);
198	    lv_obj_add_event_cb(objects.screen_main, screen_gesture_cb, LV_EVENT_GESTURE, NULL);
199	    uint32_t tab_count = lv_obj_get_child_cnt(content);
200	    if (tab_count > UI_PAGER_MAX_DOTS) {
201	        tab_count = UI_PAGER_MAX_DOTS;
202	    }
203	    s_page_dot_count = tab_count;
204	
205	    // The legacy score meter (generated by EEZ Studio) is replaced by the
206	    // eco-tree view; delete it before the first render so it never shows up.
207	    if (objects.meter_score != NULL) {
208	        lv_obj_del(objects.meter_score);
209	        objects.meter_score = NULL;
210	    }
211	
212	    // Full-bleed pages: strip the theme padding from every tab page and the
213	    // corner radius from each page's root container. The old "framed card"
214	    // look is gone — page backgrounds (grey on CAN/SAVE, meadow on AI) run
215	    // edge to edge.
216	    for (uint32_t i = 0; i < lv_obj_get_child_cnt(content); i++) {
217	        lv_obj_t *page = lv_obj_get_child(content, i);
218	        lv_obj_set_style_pad_all(page, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
219	        for (uint32_t j = 0; j < lv_obj_get_child_cnt(page); j++) {
220	            lv_obj_set_style_radius(lv_obj_get_child(page, j), 0, LV_PART_MAIN | LV_STATE_DEFAULT);
221	        }
222	    }
223	
224	    // Scale CAN tiles up to fill their grid cells; fixed gaps between tiles.
225	    // pad_bottom 30 keeps the last grid row above the dot indicator overlay.
226	    if (objects.container_can != NULL) {
227	        lv_obj_set_style_pad_left(objects.container_can, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
228	        lv_obj_set_style_pad_right(objects.container_can, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
229	        lv_obj_set_style_pad_bottom(objects.container_can, 30, LV_PART_MAIN | LV_STATE_DEFAULT);
230	        lv_obj_set_style_pad_row(objects.container_can, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
231	        lv_obj_set_style_pad_column(objects.container_can, 12, LV_PART_MAIN | LV_STATE_DEFAULT);
232	        for (uint32_t j = 0; j < lv_obj_get_child_cnt(objects.container_can); j++) {
233	            lv_obj_t *tile = lv_obj_get_child(objects.container_can, j);
234	            lv_obj_set_style_grid_cell_x_align(tile, LV_GRID_ALIGN_STRETCH, LV_PART_MAIN | LV_STATE_DEFAULT);
235	            lv_obj_set_style_grid_cell_y_align(tile, LV_GRID_ALIGN_STRETCH, LV_PART_MAIN | LV_STATE_DEFAULT);
236	            // Spread title/value labels over the taller tile.
237	            lv_obj_set_style_flex_main_place(tile, LV_FLEX_ALIGN_SPACE_EVENLY, LV_PART_MAIN | LV_STATE_DEFAULT);
238	            center_labels_recursive(tile);
239	        }
240	    }
241	
242	    // Rework the SAVE page into two independent columns: [SD + Settings] on
243	    // the left, [WiFi + Time] on the right. In the original row-based layout
244	    // the taller WiFi box dictated the first row's height, leaving a gap
245	    // between the (shorter) SD box and the Settings box below it. The
246	    // generated row containers are repurposed as columns and the boxes are
247	    // re-parented at runtime. pad_bottom 30 keeps content above the dots.
248	    if (objects.container_save != NULL && objects.container_sd_wifi != NULL &&
249	        objects.container_settings != NULL && objects.container_sd != NULL &&
250	        objects.container_wifi != NULL && objects.container_bl != NULL &&
251	        objects.container_rtc != NULL) {
252	        lv_obj_set_style_flex_flow(objects.container_save, LV_FLEX_FLOW_ROW, LV_PART_MAIN | LV_STATE_DEFAULT);
253	        lv_obj_set_style_flex_main_place(objects.container_save, LV_FLEX_ALIGN_SPACE_EVENLY,
254	                                         LV_PART_MAIN | LV_STATE_DEFAULT);
255	        lv_obj_set_style_pad_bottom(objects.container_save, 30, LV_PART_MAIN | LV_STATE_DEFAULT);
256	
257	        // Left column: SD (content-sized) + Settings (fills the rest).
258	        lv_obj_t *col_left = objects.container_sd_wifi;
259	        lv_obj_set_size(col_left, LV_PCT(50), LV_PCT(100));
260	        lv_obj_set_style_flex_flow(col_left, LV_FLEX_FLOW_COLUMN, LV_PART_MAIN | LV_STATE_DEFAULT);
261	        lv_obj_set_style_pad_row(col_left, 10, LV_PART_MAIN | LV_STATE_DEFAULT);
262	
263	        // Right column: WiFi (fixed) + Time (fills the rest).
264	        lv_obj_t *col_right = objects.container_settings;
265	        lv_obj_set_size(col_right, LV_PCT(48), LV_PCT(100));
266	        lv_obj_set_flex_grow(col_right, 0);
267	        lv_obj_set_style_flex_flow(col_right, LV_FLEX_FLOW_COLUMN, LV_PART_MAIN | LV_STATE_DEFAULT);
268	        lv_obj_set_style_pad_row(col_right, 10, LV_PART_MAIN | LV_STATE_DEFAULT);
269	
270	        lv_obj_set_parent(objects.container_bl, col_left);
271	        lv_obj_set_parent(objects.container_wifi, col_right);
272	        lv_obj_move_to_index(objects.container_wifi, 0);
273	
274	        lv_obj_set_size(objects.container_sd, LV_PCT(100), LV_SIZE_CONTENT);
275	        lv_obj_set_size(objects.container_bl, LV_PCT(100), LV_SIZE_CONTENT);
276	        lv_obj_set_flex_grow(objects.container_bl, 1);
277	        lv_obj_set_size(objects.container_wifi, LV_PCT(100), 260);
278	        lv_obj_set_size(objects.container_rtc, LV_PCT(100), LV_SIZE_CONTENT);
279	        lv_obj_set_flex_grow(objects.container_rtc, 1);
280	    }
281	
282	    // Dot indicator overlay at the bottom of the screen.
283	    lv_obj_t *dots = lv_obj_create(objects.screen_main);
284	    lv_obj_remove_style_all(dots);
285	    lv_obj_set_size(dots, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
286	    lv_obj_set_flex_flow(dots, LV_FLEX_FLOW_ROW);
287	    lv_obj_set_flex_align(dots, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
288	    lv_obj_set_style_pad_column(dots, 10, LV_PART_MAIN | LV_STATE_DEFAULT);
289	    lv_obj_clear_flag(dots, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
290	    lv_obj_align(dots, LV_ALIGN_BOTTOM_MID, 0, -8);
291	
292	    for (uint32_t i = 0; i < tab_count; i++) {
293	        lv_obj_t *dot = lv_obj_create(dots);
294	        lv_obj_remove_style_all(dot);
295	        lv_obj_set_size(dot, 10, 10);
296	        lv_obj_set_style_radius(dot, LV_RADIUS_CIRCLE, LV_PART_MAIN | LV_STATE_DEFAULT);
297	        lv_obj_set_style_bg_opa(dot, LV_OPA_COVER, LV_PART_MAIN | LV_STATE_DEFAULT);
298	        lv_obj_clear_flag(dot, LV_OBJ_FLAG_CLICKABLE);
299	        s_page_dots[i] = dot;
300	    }
301	
302	    lv_obj_add_event_cb(tv, tabview_page_changed_cb, LV_EVENT_VALUE_CHANGED, NULL);
303	    update_page_dots(lv_tabview_get_tab_act(tv));
304	}
