338	void action_click_new_file(lv_event_t * e) {
339	    if (!s_bl_user_control) {
340	        lv_label_set_text(objects.label_status, "Status: ignition mode");
341	        return;
342	    }
343	
344	    ESP_LOGI(TAG, "action_click_new_file triggered");
345	    if (objects.panel_new_file != NULL) {
346	        lv_obj_clear_flag(objects.panel_new_file, LV_OBJ_FLAG_HIDDEN);
