352	void action_click_start(lv_event_t * e) {
353	    if (!s_bl_user_control) {
354	        lv_label_set_text(objects.label_status, "Status: ignition mode");
355	        return;
356	    }
357	
358	    ESP_LOGI(TAG, "action_click_start triggered");
359	    
360	    const char * filename = lv_textarea_get_text(objects.textarea_filename);
361	    if (strlen(filename) > 0) {
362	        if (sd_card_start_recording(filename) != ESP_OK) {
363	            lv_label_set_text(objects.label_status, "Status: start failed");
364	            return;
365	        }
366	        
367	        // Hide panel
368	        if (objects.panel_new_file != NULL) {
369	            lv_obj_add_flag(objects.panel_new_file, LV_OBJ_FLAG_HIDDEN);
370	        }
371	        
372	        // Update labels 
373	        char buf[156];
374	        snprintf(buf, sizeof(buf), "File: %s", filename);
375	        lv_label_set_text(objects.label_file, buf);
376	        lv_label_set_text(objects.label_status, "Status: recording...");
377	        
378	        // Button handling
379	        lv_obj_clear_state(objects.button_save, LV_STATE_DISABLED);
380	        lv_obj_add_state(objects.button_new__file, LV_STATE_DISABLED);
381	        
382	        static bool status_timer_created = false;
383	        if (!status_timer_created) {
384	            lv_timer_create(update_status_task, 5000, NULL);
385	            status_timer_created = true;
386	        }
387	    }
388	}
