796	// Screenshot: hold the top-left corner of any page for 1s to dump the current
797	// screen to a BMP on the SD card. A transparent trigger sits on the LVGL top
798	// layer (like the brightness dim overlay) so it works on every tab without
799	// touching the EEZ Studio-generated screens.
800	#define UI_SCREENSHOT_HOLD_MS      1000
801	#define UI_SCREENSHOT_CORNER_SIZE  90
802	#define SCREENSHOT_DIR             MOUNT_POINT "/snapshots"
803	
804	static TickType_t s_screenshot_press_start = 0;
805	
806	#pragma pack(push, 1)
807	typedef struct {
808	    uint16_t type;
809	    uint32_t size;
810	    uint16_t reserved1;
811	    uint16_t reserved2;
812	    uint32_t offset;
813	} bmp_file_header_t;
814	
815	typedef struct {
816	    uint32_t header_size;
817	    int32_t width;
818	    int32_t height;
819	    uint16_t planes;
820	    uint16_t bpp;
821	    uint32_t compression;
822	    uint32_t image_size;
823	    int32_t x_ppm;
824	    int32_t y_ppm;
825	    uint32_t colors_used;
826	    uint32_t colors_important;
827	} bmp_info_header_t;
828	#pragma pack(pop)
829	
830	static esp_err_t screenshot_build_filename(char *buffer, size_t buffer_size) {
831	    struct tm rtc_time;
832	    if (rtc_manager_read_time(&rtc_time) == ESP_OK && rtc_manager_time_is_valid(&rtc_time)) {
833	        int written = snprintf(buffer, buffer_size, "%s/screenshot_%04d%02d%02d_%02d%02d%02d.bmp",
834	                               SCREENSHOT_DIR,
835	                               rtc_time.tm_year + 1900, rtc_time.tm_mon + 1, rtc_time.tm_mday,
836	                               rtc_time.tm_hour, rtc_time.tm_min, rtc_time.tm_sec);
837	        return (written > 0 && (size_t)written < buffer_size) ? ESP_OK : ESP_ERR_INVALID_SIZE;
838	    }
839	
840	    uint32_t uptime_ms = (uint32_t)(esp_timer_get_time() / 1000ULL);
841	    int written = snprintf(buffer, buffer_size, "%s/screenshot_%010lu.bmp", SCREENSHOT_DIR, (unsigned long)uptime_ms);
842	    return (written > 0 && (size_t)written < buffer_size) ? ESP_OK : ESP_ERR_INVALID_SIZE;
843	}
844	
845	// Converts the RGB565 snapshot to a 24-bit uncompressed BMP (bottom-up rows)
846	// for maximum viewer compatibility.
847	static esp_err_t screenshot_write_bmp(const char *filepath, const lv_img_dsc_t *snap) {
848	    uint32_t width = snap->header.w;
849	    uint32_t height = snap->header.h;
850	    uint32_t row_bytes = width * 3;
851	    uint32_t padding = (4 - (row_bytes % 4)) % 4;
852	    uint32_t image_size = (row_bytes + padding) * height;
853	
854	    bmp_file_header_t file_header = {
855	        .type = 0x4D42, // "BM"
856	        .size = (uint32_t)(sizeof(bmp_file_header_t) + sizeof(bmp_info_header_t) + image_size),
857	        .reserved1 = 0,
858	        .reserved2 = 0,
859	        .offset = (uint32_t)(sizeof(bmp_file_header_t) + sizeof(bmp_info_header_t)),
860	    };
861	
862	    bmp_info_header_t info_header = {
863	        .header_size = sizeof(bmp_info_header_t),
864	        .width = (int32_t)width,
865	        .height = (int32_t)height,
866	        .planes = 1,
867	        .bpp = 24,
868	        .compression = 0,
869	        .image_size = image_size,
870	        .x_ppm = 0,
871	        .y_ppm = 0,
872	        .colors_used = 0,
873	        .colors_important = 0,
874	    };
875	
876	    FILE *f = fopen(filepath, "wb");
877	    if (f == NULL) {
878	        ESP_LOGE(TAG, "Failed to open %s for screenshot (errno=%d)", filepath, errno);
879	        return ESP_FAIL;
880	    }
881	
882	    esp_err_t ret = ESP_OK;
883	    if (fwrite(&file_header, sizeof(file_header), 1, f) != 1 ||
884	        fwrite(&info_header, sizeof(info_header), 1, f) != 1) {
885	        ret = ESP_FAIL;
886	    }
887	
888	    if (ret == ESP_OK) {
889	        uint8_t *row_buf = malloc(row_bytes + padding);
890	        if (row_buf == NULL) {
891	            ret = ESP_ERR_NO_MEM;
892	        } else {
893	            memset(row_buf + row_bytes, 0, padding);
894	            const uint16_t *pixels = (const uint16_t *)snap->data;
895	
896	            // BMP rows are stored bottom-up; the snapshot buffer is top-down.
897	            for (int32_t y = (int32_t)height - 1; y >= 0 && ret == ESP_OK; y--) {
898	                const uint16_t *src_row = pixels + (uint32_t)y * width;
899	                for (uint32_t x = 0; x < width; x++) {
900	                    uint16_t px = src_row[x];
901	                    uint8_t r5 = (px >> 11) & 0x1F;
902	                    uint8_t g6 = (px >> 5) & 0x3F;
903	                    uint8_t b5 = px & 0x1F;
904	                    row_buf[x * 3 + 0] = (uint8_t)((b5 << 3) | (b5 >> 2));
905	                    row_buf[x * 3 + 1] = (uint8_t)((g6 << 2) | (g6 >> 4));
906	                    row_buf[x * 3 + 2] = (uint8_t)((r5 << 3) | (r5 >> 2));
907	                }
908	                if (fwrite(row_buf, row_bytes + padding, 1, f) != 1) {
909	                    ret = ESP_FAIL;
910	                }
911	            }
912	            free(row_buf);
913	        }
914	    }
915	
916	    fclose(f);
917	    if (ret != ESP_OK) {
918	        remove(filepath);
919	    }
920	    return ret;
921	}
922	
923	static esp_err_t screenshot_capture_and_save(char *out_path, size_t out_path_size) {
924	    struct stat st;
925	    if (stat(SCREENSHOT_DIR, &st) != 0 && mkdir(SCREENSHOT_DIR, 0775) != 0 && errno != EEXIST) {
926	        ESP_LOGE(TAG, "Failed to create %s (errno=%d)", SCREENSHOT_DIR, errno);
927	        return ESP_FAIL;
928	    }
929	
930	    char filepath[192];
931	    if (screenshot_build_filename(filepath, sizeof(filepath)) != ESP_OK) {
932	        return ESP_FAIL;
933	    }
934	
935	    lv_img_dsc_t *snap = lv_snapshot_take(lv_scr_act(), LV_IMG_CF_TRUE_COLOR);
936	    if (snap == NULL) {
937	        ESP_LOGE(TAG, "Failed to capture screenshot snapshot");
938	        return ESP_FAIL;
939	    }
940	
941	    esp_err_t ret = screenshot_write_bmp(filepath, snap);
942	    lv_snapshot_free(snap);
943	
944	    if (ret == ESP_OK) {
945	        ESP_LOGI(TAG, "Screenshot saved: %s", filepath);
946	        if (out_path != NULL) {
947	            snprintf(out_path, out_path_size, "%s", filepath);
948	        }
949	    }
950	    return ret;
951	}
