962	    lv_obj_set_style_text_color(toast, lv_color_white(), LV_PART_MAIN | LV_STATE_DEFAULT);
963	    lv_obj_set_style_pad_all(toast, 10, LV_PART_MAIN | LV_STATE_DEFAULT);
964	    lv_obj_set_style_radius(toast, 8, LV_PART_MAIN | LV_STATE_DEFAULT);
