1156	    \centering
1157	    \includegraphics[width=0.7\linewidth]{screenshot_20260708_104211.png}
1158	    \caption{Sad na wczesnym etapie zapełniania.}
1159	    \label{fig:sad-wczesny}
1160	\end{figure}
1161	
