1240	    \includegraphics[width=0.75\linewidth]{ustawienia_sync.png}
1241	    \caption{Ekran ustawień: nagrywanie danych, sieć bezprzewodowa, synchronizacja czasu, jasność ekranu.}
1242	    \label{fig:ustawienia}
1243	\end{figure}
