import re

for fname in [
    r"d:\Studia\mgr\praca magisterska\PM_latex\main.tex",
    r"d:\Studia\mgr\praca magisterska\PM_latex\tex\3-projekt.tex",
]:
    content = open(fname, encoding="utf-8").read()
    lines = content.split("\n")
    depth = 0
    comment_re = re.compile(r"(?<!\\)%.*")
    for lineno, line in enumerate(lines, 1):
        cleaned = comment_re.sub("", line)
        for ch in cleaned:
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth < 0:
                    print(f"{fname}: linia {lineno}: nadmiarowy }} -> {line.strip()[:120]}")
                    depth = 0
    print(fname, "koncowa glebokosc:", depth)

